"""All 16 bespoke simulators for Class 5 Maths Chapter 1."""

SIMULATORS = {
    1: '\n<div class="space-y-3">\n    <div class="p-3 bg-slate-950 rounded-xl border border-slate-800 text-center">\n        <span class="text-xs font-bold text-amber-400 uppercase tracking-wider block mb-1">Transport Evolution & Speed Explorer</span>\n        <p class="text-[11px] text-slate-400">Step through human travel history: from walking at 4 km/h to orbital spacecraft at 28,000 km/h!</p>\n    </div>\n    <div class="relative h-60 bg-gradient-to-b from-slate-950 via-slate-900 to-slate-950 rounded-xl border border-slate-800 overflow-hidden p-2 flex items-center justify-center">\n        <svg viewBox="0 0 400 240" class="w-full h-full">\n            <!-- Road / Horizon Track -->\n            <line x1="20" y1="180" x2="380" y2="180" stroke="#334155" stroke-width="3"/>\n            <line x1="20" y1="180" x2="380" y2="180" stroke="#f59e0b" stroke-width="1.5" stroke-dasharray="6,6"/>\n\n            <!-- Dynamic Vehicle Visual Stage -->\n            <g id="transportVehicleGraphic">\n                <!-- Mode 1 (Default): Walking Traveller -->\n                <circle cx="200" cy="115" r="14" fill="#fed7aa"/>\n                <path d="M190,130 L210,130 L205,160 L195,160 Z" fill="#0284c7"/>\n                <line x1="195" y1="160" x2="190" y2="180" stroke="#1e293b" stroke-width="3"/>\n                <line x1="205" y1="160" x2="215" y2="180" stroke="#1e293b" stroke-width="3"/>\n                <!-- Walking Stick -->\n                <line x1="214" y1="135" x2="218" y2="180" stroke="#78350f" stroke-width="2"/>\n                <text x="200" y="90" fill="#fef08a" font-size="9" font-weight="bold" text-anchor="middle">Ancient Walking on Foot</text>\n            </g>\n\n            <!-- Speedometer Display Card -->\n            <rect x="25" y="20" width="135" height="46" rx="6" fill="#020617" stroke="#334155" opacity="0.95"/>\n            <text x="35" y="33" fill="#94a3b8" font-size="7">AVERAGE SPEED</text>\n            <text id="sim1SpeedText" x="35" y="48" fill="#38bdf8" font-size="11" font-weight="bold">4 km/h (Walking)</text>\n            <text id="sim1Distance10h" x="35" y="59" fill="#cbd5e1" font-size="7">Distance in 10h: 40 km</text>\n        </svg>\n    </div>\n    <div class="grid grid-cols-4 gap-1.5">\n        <button onclick="setTransportMode(\'walk\')" class="p-1.5 bg-slate-900 hover:bg-slate-800 rounded border border-amber-500/50 text-[10px] font-bold text-amber-300">\n            Walking (4 km/h)\n        </button>\n        <button onclick="setTransportMode(\'cart\')" class="p-1.5 bg-slate-900 hover:bg-slate-800 rounded border border-emerald-500/50 text-[10px] font-bold text-emerald-300">\n            Cart (5 km/h)\n        </button>\n        <button onclick="setTransportMode(\'train\')" class="p-1.5 bg-slate-900 hover:bg-slate-800 rounded border border-sky-500/50 text-[10px] font-bold text-sky-300">\n            Train (120 km/h)\n        </button>\n        <button onclick="setTransportMode(\'rocket\')" class="p-1.5 bg-slate-900 hover:bg-slate-800 rounded border border-purple-500/50 text-[10px] font-bold text-purple-300">\n            Rocket (28,000 km/h)\n        </button>\n    </div>\n    <div id="sim1Status" class="p-2 bg-slate-900/60 rounded-lg border border-slate-800 text-[11px] text-slate-300">\n        <strong>Walking (Ancient Era):</strong> Travellers walked at 3–5 km/h. To journey across India from Varanasi to Kanyakumari took over 6 months of steady walking!\n    </div>\n</div>\n',
    2: '\n<div class="space-y-3">\n    <div class="p-3 bg-slate-950 rounded-xl border border-slate-800 text-center">\n        <span class="text-xs font-bold text-emerald-400 uppercase tracking-wider block mb-1">Ten Thousand: Bundling Base-10 Units</span>\n        <p class="text-[11px] text-slate-400">Add thousands one by one. Watch 9,000 + 1,000 bundle into Ten Thousand (10,000)!</p>\n    </div>\n    <div class="relative h-60 bg-gradient-to-b from-slate-950 via-slate-900 to-slate-950 rounded-xl border border-slate-800 overflow-hidden p-2 flex items-center justify-center">\n        <svg viewBox="0 0 400 240" class="w-full h-full">\n            <!-- 10 Thousand Cube Bundles Container (2 rows of 5) -->\n            <g id="thousandBlocksGroup" transform="translate(45, 55)">\n                <!-- Blocks rendered dynamically by JS -->\n            </g>\n\n            <!-- Counter Readout Box -->\n            <rect x="255" y="45" width="125" height="135" rx="8" fill="#020617" stroke="#334155" opacity="0.95"/>\n            <text x="317" y="65" fill="#94a3b8" font-size="8" font-weight="bold" text-anchor="middle">TOTAL COUNT</text>\n            <text id="sim2BundleTotal" x="317" y="98" fill="#4ade80" font-size="20" font-weight="bold" text-anchor="middle">1,000</text>\n            <text id="sim2BundleWords" x="317" y="118" fill="#fde047" font-size="8" font-weight="bold" text-anchor="middle">One Thousand</text>\n            <text id="sim2BundleMath" x="317" y="145" fill="#38bdf8" font-size="7.5" text-anchor="middle">1 × 1,000 = 1,000</text>\n        </svg>\n    </div>\n    <div class="flex items-center gap-2">\n        <button onclick="addThousandBlock()" class="flex-1 p-2 bg-emerald-600 hover:bg-emerald-500 rounded-lg text-xs font-bold text-white">\n            + Add 1,000 Block\n        </button>\n        <button onclick="resetThousandBlocks()" class="p-2 bg-slate-800 hover:bg-slate-700 rounded-lg text-xs font-bold text-slate-300">\n            Reset (1,000)\n        </button>\n        <button onclick="jumpToTenThousand()" class="p-2 bg-amber-600 hover:bg-amber-500 rounded-lg text-xs font-bold text-white">\n            Bundle to 10,000\n        </button>\n    </div>\n    <div id="sim2Status" class="p-2 bg-slate-900/60 rounded-lg border border-slate-800 text-[11px] text-slate-300">\n        <strong>Base-10 Bundling:</strong> 10 Ones = 1 Ten | 10 Tens = 1 Hundred | 10 Hundreds = 1 Thousand | <strong>10 Thousands = 1 Ten Thousand (10,000)</strong>!\n    </div>\n</div>\n',
    3: '\n<div class="space-y-3">\n    <div class="p-3 bg-slate-950 rounded-xl border border-slate-800 text-center">\n        <span class="text-xs font-bold text-sky-400 uppercase tracking-wider block mb-1">Indian Place Value Spike Abacus (TTh, Th, H, T, O)</span>\n        <p class="text-[11px] text-slate-400">Add beads to each spike and see how each position scales by powers of 10!</p>\n    </div>\n    <div class="relative h-60 bg-gradient-to-b from-slate-950 via-slate-900 to-slate-950 rounded-xl border border-slate-800 overflow-hidden p-2 flex items-center justify-center">\n        <svg viewBox="0 0 400 240" class="w-full h-full">\n            <!-- Abacus Wooden Base -->\n            <rect x="30" y="180" width="340" height="22" rx="4" fill="#78350f" stroke="#451a03" stroke-width="1.5"/>\n\n            <!-- 5 Spikes (TTh: 70, Th: 135, H: 200, T: 265, O: 330) -->\n            <!-- TTh Spike -->\n            <line x1="70" y1="50" x2="70" y2="180" stroke="#94a3b8" stroke-width="2.5"/>\n            <text x="70" y="196" fill="#fde047" font-size="8" font-weight="bold" text-anchor="middle">TTh</text>\n            <text x="70" y="210" fill="#94a3b8" font-size="7" text-anchor="middle">(10,000)</text>\n\n            <!-- Th Spike -->\n            <line x1="135" y1="50" x2="135" y2="180" stroke="#94a3b8" stroke-width="2.5"/>\n            <text x="135" y="196" fill="#38bdf8" font-size="8" font-weight="bold" text-anchor="middle">Th</text>\n            <text x="135" y="210" fill="#94a3b8" font-size="7" text-anchor="middle">(1,000)</text>\n\n            <!-- H Spike -->\n            <line x1="200" y1="50" x2="200" y2="180" stroke="#94a3b8" stroke-width="2.5"/>\n            <text x="200" y="196" fill="#4ade80" font-size="8" font-weight="bold" text-anchor="middle">H</text>\n            <text x="200" y="210" fill="#94a3b8" font-size="7" text-anchor="middle">(100)</text>\n\n            <!-- T Spike -->\n            <line x1="265" y1="50" x2="265" y2="180" stroke="#94a3b8" stroke-width="2.5"/>\n            <text x="265" y="196" fill="#fb923c" font-size="8" font-weight="bold" text-anchor="middle">T</text>\n            <text x="265" y="210" fill="#94a3b8" font-size="7" text-anchor="middle">(10)</text>\n\n            <!-- O Spike -->\n            <line x1="330" y1="50" x2="330" y2="180" stroke="#94a3b8" stroke-width="2.5"/>\n            <text x="330" y="196" fill="#f472b6" font-size="8" font-weight="bold" text-anchor="middle">O</text>\n            <text x="330" y="210" fill="#94a3b8" font-size="7" text-anchor="middle">(1)</text>\n\n            <!-- Beads Container -->\n            <g id="abacusBeadsLayer"></g>\n\n            <!-- Top Value Pill -->\n            <rect x="120" y="12" width="160" height="30" rx="6" fill="#020617" stroke="#334155" opacity="0.95"/>\n            <text id="abacusTotalText" x="200" y="32" fill="#38bdf8" font-size="12" font-weight="bold" text-anchor="middle">Value: 35,427</text>\n        </svg>\n    </div>\n    <div class="grid grid-cols-5 gap-1.5">\n        <button onclick="incrementAbacusSpike(\'tth\')" class="p-1.5 bg-slate-900 hover:bg-slate-800 rounded border border-yellow-500/50 text-[10px] font-bold text-yellow-300">\n            +1 TTh\n        </button>\n        <button onclick="incrementAbacusSpike(\'th\')" class="p-1.5 bg-slate-900 hover:bg-slate-800 rounded border border-sky-500/50 text-[10px] font-bold text-sky-300">\n            +1 Th\n        </button>\n        <button onclick="incrementAbacusSpike(\'h\')" class="p-1.5 bg-slate-900 hover:bg-slate-800 rounded border border-emerald-500/50 text-[10px] font-bold text-emerald-300">\n            +1 H\n        </button>\n        <button onclick="incrementAbacusSpike(\'t\')" class="p-1.5 bg-slate-900 hover:bg-slate-800 rounded border border-orange-500/50 text-[10px] font-bold text-orange-300">\n            +1 T\n        </button>\n        <button onclick="incrementAbacusSpike(\'o\')" class="p-1.5 bg-slate-900 hover:bg-slate-800 rounded border border-pink-500/50 text-[10px] font-bold text-pink-300">\n            +1 O\n        </button>\n    </div>\n    <div id="sim3Status" class="p-2 bg-slate-900/60 rounded-lg border border-slate-800 text-[11px] text-slate-300">\n        <strong>Expanded Form:</strong> 30,000 + 5,000 + 400 + 20 + 7 = <strong>35,427</strong> (Thirty-five thousand, four hundred twenty-seven).\n    </div>\n</div>\n',
    4: '\n<div class="space-y-3">\n    <div class="p-3 bg-slate-950 rounded-xl border border-slate-800 text-center">\n        <span class="text-xs font-bold text-teal-400 uppercase tracking-wider block mb-1">Indian Comma System & Period Formatter</span>\n        <p class="text-[11px] text-slate-400">See how commas group digits into Thousands Period and Ones Period (XX,XXX)!</p>\n    </div>\n    <div class="relative h-60 bg-gradient-to-b from-slate-950 via-slate-900 to-slate-950 rounded-xl border border-slate-800 overflow-hidden p-2 flex items-center justify-center">\n        <svg viewBox="0 0 400 240" class="w-full h-full">\n            <!-- Period Groups Container Card -->\n            <g transform="translate(50, 40)">\n                <!-- Thousands Period Box (2 digits) -->\n                <rect x="0" y="0" width="125" height="100" rx="8" fill="#0c4a6e" stroke="#38bdf8" stroke-width="2"/>\n                <text x="62" y="24" fill="#bae6fd" font-size="8" font-weight="bold" text-anchor="middle">THOUSANDS PERIOD</text>\n                <text id="commaPeriodTTh" x="62" y="68" fill="#ffffff" font-size="28" font-weight="bold" text-anchor="middle">48</text>\n                <text x="62" y="88" fill="#7dd3fc" font-size="7.5" text-anchor="middle">TTh & Th Columns</text>\n\n                <!-- Comma Divider Bead -->\n                <circle cx="140" cy="65" r="4" fill="#f59e0b"/>\n                <path d="M140,65 Q136,75 142,78" stroke="#f59e0b" stroke-width="2" fill="none"/>\n                <text x="140" y="95" fill="#fef08a" font-size="9" font-weight="bold" text-anchor="middle">,</text>\n\n                <!-- Ones Period Box (3 digits) -->\n                <rect x="155" y="0" width="145" height="100" rx="8" fill="#064e3b" stroke="#4ade80" stroke-width="2"/>\n                <text x="227" y="24" fill="#bbf7d0" font-size="8" font-weight="bold" text-anchor="middle">ONES PERIOD</text>\n                <text id="commaPeriodOnes" x="227" y="68" fill="#ffffff" font-size="28" font-weight="bold" text-anchor="middle">215</text>\n                <text x="227" y="88" fill="#86efac" font-size="7.5" text-anchor="middle">H, T, O Columns</text>\n            </g>\n\n            <!-- Combined Full Numeral Banner -->\n            <rect x="50" y="160" width="300" height="42" rx="6" fill="#020617" stroke="#334155" opacity="0.95"/>\n            <text id="fullNumeralWithComma" x="200" y="180" fill="#fde047" font-size="13" font-weight="bold" text-anchor="middle">Numeral: 48,215</text>\n            <text id="fullWordNameText" x="200" y="194" fill="#cbd5e1" font-size="7.5" text-anchor="middle">Forty-eight thousand, two hundred fifteen</text>\n        </svg>\n    </div>\n    <div class="grid grid-cols-3 gap-2">\n        <button onclick="setExampleNumber(\'48215\')" class="p-2 bg-sky-900 hover:bg-sky-800 border border-sky-500 rounded-lg text-xs font-bold text-sky-200">\n            Example 1: 48,215\n        </button>\n        <button onclick="setExampleNumber(\'70008\')" class="p-2 bg-emerald-900 hover:bg-emerald-800 border border-emerald-500 rounded-lg text-xs font-bold text-emerald-200">\n            Example 2: 70,008\n        </button>\n        <button onclick="setExampleNumber(\'99999\')" class="p-2 bg-amber-900 hover:bg-amber-800 border border-amber-500 rounded-lg text-xs font-bold text-amber-200">\n            Example 3: 99,999\n        </button>\n    </div>\n    <div id="sim4Status" class="p-2 bg-slate-900/60 rounded-lg border border-slate-800 text-[11px] text-slate-300">\n        <strong>Indian Rule:</strong> First comma after 3 digits from right (Ones, Tens, Hundreds). The next period has 2 digits (Thousands). So 5 digits are written as <strong>48,215</strong>!\n    </div>\n</div>\n',
    5: '\n<div class="space-y-3">\n    <div class="p-3 bg-slate-950 rounded-xl border border-slate-800 text-center">\n        <span class="text-xs font-bold text-amber-400 uppercase tracking-wider block mb-1">Vehicle Odometer Sorter (Ascending vs Descending)</span>\n        <p class="text-[11px] text-slate-400">Compare 4 vehicle travel distances. Sort them in ascending or descending order!</p>\n    </div>\n    <div class="relative h-60 bg-gradient-to-b from-slate-950 via-slate-900 to-slate-950 rounded-xl border border-slate-800 overflow-hidden p-2 flex items-center justify-center">\n        <svg viewBox="0 0 400 240" class="w-full h-full">\n            <!-- 4 Odometer Distance Cards -->\n            <g id="odometerBarsGroup" transform="translate(30, 30)">\n                <!-- Vehicle A: Car (24,150 km) -->\n                <rect id="barA" x="0" y="10" width="180" height="28" rx="4" fill="#0284c7" opacity="0.85"/>\n                <text x="10" y="28" fill="#ffffff" font-size="8" font-weight="bold">Car A: 24,150 km</text>\n\n                <!-- Vehicle B: Bus (18,900 km) -->\n                <rect id="barB" x="0" y="48" width="140" height="28" rx="4" fill="#15803d" opacity="0.85"/>\n                <text x="10" y="66" fill="#ffffff" font-size="8" font-weight="bold">Bus B: 18,900 km</text>\n\n                <!-- Vehicle C: Train (45,300 km) -->\n                <rect id="barC" x="0" y="86" width="300" height="28" rx="4" fill="#d97706" opacity="0.85"/>\n                <text x="10" y="104" fill="#ffffff" font-size="8" font-weight="bold">Train C: 45,300 km</text>\n\n                <!-- Vehicle D: Truck (32,800 km) -->\n                <rect id="barD" x="0" y="124" width="225" height="28" rx="4" fill="#7c3aed" opacity="0.85"/>\n                <text x="10" y="142" fill="#ffffff" font-size="8" font-weight="bold">Truck D: 32,800 km</text>\n            </g>\n\n            <!-- Order Indicator Label -->\n            <rect x="25" y="195" width="350" height="30" rx="5" fill="#020617" stroke="#334155" opacity="0.95"/>\n            <text id="orderSequenceText" x="200" y="214" fill="#38bdf8" font-size="9" font-weight="bold" text-anchor="middle">Unsorted: Compare Ten Thousands (TTh) digits first!</text>\n        </svg>\n    </div>\n    <div class="grid grid-cols-2 gap-2">\n        <button onclick="sortOdometers(\'ascending\')" class="p-2 bg-sky-600 hover:bg-sky-500 rounded-lg text-xs font-bold text-white">\n            Ascending Order (Smallest to Largest)\n        </button>\n        <button onclick="sortOdometers(\'descending\')" class="p-2 bg-emerald-600 hover:bg-emerald-500 rounded-lg text-xs font-bold text-white">\n            Descending Order (Largest to Smallest)\n        </button>\n    </div>\n    <div id="sim5Status" class="p-2 bg-slate-900/60 rounded-lg border border-slate-800 text-[11px] text-slate-300">\n        <strong>Comparison Rule:</strong> Look at the Ten Thousands digit first: 1 in 18,900 < 2 in 24,150 < 3 in 32,800 < 4 in 45,300.\n    </div>\n</div>\n',
    6: '\n<div class="space-y-3">\n    <div class="p-3 bg-slate-950 rounded-xl border border-slate-800 text-center">\n        <span class="text-xs font-bold text-rose-400 uppercase tracking-wider block mb-1">Digit Swap Lab (The Power of Position)</span>\n        <p class="text-[11px] text-slate-400">Swap digits in 25,480 to discover how position massively changes a number\'s value!</p>\n    </div>\n    <div class="relative h-60 bg-gradient-to-b from-slate-950 via-slate-900 to-slate-950 rounded-xl border border-slate-800 overflow-hidden p-2 flex items-center justify-center">\n        <svg viewBox="0 0 400 240" class="w-full h-full">\n            <!-- 5 Clickable Digit Tiles -->\n            <g id="digitTilesGroup" transform="translate(65, 50)">\n                <!-- Tile 1 (TTh) -->\n                <rect id="tile0" x="0" y="0" width="45" height="60" rx="6" fill="#0c4a6e" stroke="#38bdf8" stroke-width="2"/>\n                <text id="digitVal0" x="22" y="38" fill="#ffffff" font-size="24" font-weight="bold" text-anchor="middle">2</text>\n                <text x="22" y="54" fill="#7dd3fc" font-size="7" text-anchor="middle">TTh</text>\n\n                <!-- Tile 2 (Th) -->\n                <rect id="tile1" x="55" y="0" width="45" height="60" rx="6" fill="#064e3b" stroke="#4ade80" stroke-width="2"/>\n                <text id="digitVal1" x="77" y="38" fill="#ffffff" font-size="24" font-weight="bold" text-anchor="middle">5</text>\n                <text x="77" y="54" fill="#86efac" font-size="7" text-anchor="middle">Th</text>\n\n                <!-- Tile 3 (H) -->\n                <rect id="tile2" x="110" y="0" width="45" height="60" rx="6" fill="#78350f" stroke="#fbbf24" stroke-width="2"/>\n                <text id="digitVal2" x="132" y="38" fill="#ffffff" font-size="24" font-weight="bold" text-anchor="middle">4</text>\n                <text x="132" y="54" fill="#fde68a" font-size="7" text-anchor="middle">H</text>\n\n                <!-- Tile 4 (T) -->\n                <rect id="tile3" x="165" y="0" width="45" height="60" rx="6" fill="#581c87" stroke="#c084fc" stroke-width="2"/>\n                <text id="digitVal3" x="187" y="38" fill="#ffffff" font-size="24" font-weight="bold" text-anchor="middle">8</text>\n                <text x="187" y="54" fill="#e9d5ff" font-size="7" text-anchor="middle">T</text>\n\n                <!-- Tile 5 (O) -->\n                <rect id="tile4" x="220" y="0" width="45" height="60" rx="6" fill="#881337" stroke="#fb7185" stroke-width="2"/>\n                <text id="digitVal4" x="242" y="38" fill="#ffffff" font-size="24" font-weight="bold" text-anchor="middle">0</text>\n                <text x="242" y="54" fill="#fecdd3" font-size="7" text-anchor="middle">O</text>\n            </g>\n\n            <!-- Difference Comparison Panel -->\n            <rect x="50" y="135" width="300" height="75" rx="8" fill="#020617" stroke="#334155" opacity="0.95"/>\n            <text x="200" y="154" fill="#94a3b8" font-size="8" text-anchor="middle">ORIGINAL VS NEW VALUE</text>\n            <text id="swapCompareText" x="200" y="174" fill="#fde047" font-size="11" font-weight="bold" text-anchor="middle">Original Number: 25,480</text>\n            <text id="swapDiffText" x="200" y="196" fill="#38bdf8" font-size="9" text-anchor="middle">Click below to swap digits</text>\n        </svg>\n    </div>\n    <div class="grid grid-cols-3 gap-2">\n        <button onclick="swapDigits(0, 1)" class="p-2 bg-slate-900 hover:bg-slate-800 border border-sky-500 rounded-lg text-xs font-bold text-sky-300">\n            Swap TTh & Th (2 ↔ 5)\n        </button>\n        <button onclick="swapDigits(1, 3)" class="p-2 bg-slate-900 hover:bg-slate-800 border border-purple-500 rounded-lg text-xs font-bold text-purple-300">\n            Swap Th & T (5 ↔ 8)\n        </button>\n        <button onclick="resetSwapDigits()" class="p-2 bg-slate-900 hover:bg-slate-800 border border-slate-700 rounded-lg text-xs font-bold text-slate-300">\n            Reset (25,480)\n        </button>\n    </div>\n    <div id="sim6Status" class="p-2 bg-slate-900/60 rounded-lg border border-slate-800 text-[11px] text-slate-300">\n        <strong>Position Matters:</strong> Moving digit 5 from Thousands (5,000) to Ten Thousands (50,000) increases its value by 45,000!\n    </div>\n</div>\n',
    7: '\n<div class="space-y-3">\n    <div class="p-3 bg-slate-950 rounded-xl border border-slate-800 text-center">\n        <span class="text-xs font-bold text-amber-400 uppercase tracking-wider block mb-1">Nearest Tens: The Rabbit & Carrot Number Line</span>\n        <p class="text-[11px] text-slate-400">Watch the hungry rabbit hop to the nearest multiple of 10. Halfway (5) always hops UP!</p>\n    </div>\n    <div class="relative h-60 bg-gradient-to-b from-slate-950 via-slate-900 to-slate-950 rounded-xl border border-slate-800 overflow-hidden p-2 flex items-center justify-center">\n        <svg viewBox="0 0 400 240" class="w-full h-full">\n            <!-- Number Line from 40 to 50 -->\n            <line x1="50" y1="140" x2="350" y2="140" stroke="#94a3b8" stroke-width="2.5"/>\n\n            <!-- Tick Marks 40 to 50 -->\n            <!-- 40 (Left Carrot) -->\n            <line x1="50" y1="130" x2="50" y2="150" stroke="#f59e0b" stroke-width="3"/>\n            <text x="50" y="165" fill="#f59e0b" font-size="10" font-weight="bold" text-anchor="middle">40</text>\n            <!-- Carrot Icon at 40 -->\n            <polygon points="50,115 45,100 55,100" fill="#ea580c"/>\n            <line x1="50" y1="100" x2="48" y2="92" stroke="#16a34a" stroke-width="2"/>\n\n            <!-- 45 (Midpoint) -->\n            <line x1="200" y1="132" x2="200" y2="148" stroke="#38bdf8" stroke-width="2"/>\n            <text x="200" y="165" fill="#38bdf8" font-size="9" font-weight="bold" text-anchor="middle">45 (Midway)</text>\n\n            <!-- 50 (Right Carrot) -->\n            <line x1="350" y1="130" x2="350" y2="150" stroke="#f59e0b" stroke-width="3"/>\n            <text x="350" y="165" fill="#f59e0b" font-size="10" font-weight="bold" text-anchor="middle">50</text>\n            <!-- Carrot Icon at 50 -->\n            <polygon points="350,115 345,100 355,100" fill="#ea580c"/>\n            <line x1="350" y1="100" x2="348" y2="92" stroke="#16a34a" stroke-width="2"/>\n\n            <!-- Rabbit Marker Graphic -->\n            <g id="rabbitMarker" transform="translate(140, 110)">\n                <!-- Rabbit Body -->\n                <ellipse cx="0" cy="0" rx="10" ry="7" fill="#f8fafc"/>\n                <circle cx="-7" cy="-4" r="5" fill="#f8fafc"/>\n                <!-- Long Ears -->\n                <line x1="-8" y1="-8" x2="-10" y2="-18" stroke="#f8fafc" stroke-width="2"/>\n                <line x1="-6" y1="-8" x2="-6" y2="-18" stroke="#f8fafc" stroke-width="2"/>\n                <circle cx="-8" cy="-5" r="1" fill="#020617"/>\n                <text x="0" y="24" fill="#fde047" font-size="8" font-weight="bold" text-anchor="middle">43</text>\n            </g>\n\n            <!-- Status Decision Box -->\n            <rect x="50" y="20" width="300" height="42" rx="6" fill="#020617" stroke="#334155" opacity="0.95"/>\n            <text id="rabbitDecisionText" x="200" y="38" fill="#fde047" font-size="10" font-weight="bold" text-anchor="middle">Position: 43 | Distance to 40 = 3, Distance to 50 = 7</text>\n            <text id="rabbitVerdictText" x="200" y="52" fill="#38bdf8" font-size="8" text-anchor="middle">Closer to 40 → Rounds down to 40</text>\n        </svg>\n    </div>\n    <div class="grid grid-cols-3 gap-2">\n        <button onclick="setRabbitPosition(43)" class="p-2 bg-slate-900 hover:bg-slate-800 border border-amber-500 rounded-lg text-xs font-bold text-amber-300">\n            Test 43 (Hops to 40)\n        </button>\n        <button onclick="setRabbitPosition(45)" class="p-2 bg-slate-900 hover:bg-slate-800 border border-sky-500 rounded-lg text-xs font-bold text-sky-300">\n            Test 45 (Halfway → 50)\n        </button>\n        <button onclick="setRabbitPosition(48)" class="p-2 bg-slate-900 hover:bg-slate-800 border border-emerald-500 rounded-lg text-xs font-bold text-emerald-300">\n            Test 48 (Hops to 50)\n        </button>\n    </div>\n    <div id="sim7Status" class="p-2 bg-slate-900/60 rounded-lg border border-slate-800 text-[11px] text-slate-300">\n        <strong>The Rule:</strong> Check the Ones digit! 1, 2, 3, 4 round down. 5, 6, 7, 8, 9 round up to the next ten.\n    </div>\n</div>\n',
    8: '\n<div class="space-y-3">\n    <div class="p-3 bg-slate-950 rounded-xl border border-slate-800 text-center">\n        <span class="text-xs font-bold text-sky-400 uppercase tracking-wider block mb-1">Nearest Hundreds: Highway Milestone Marker</span>\n        <p class="text-[11px] text-slate-400">Position the highway car between 300 km and 400 km. Check which hundred is closer!</p>\n    </div>\n    <div class="relative h-60 bg-gradient-to-b from-slate-950 via-slate-900 to-slate-950 rounded-xl border border-slate-800 overflow-hidden p-2 flex items-center justify-center">\n        <svg viewBox="0 0 400 240" class="w-full h-full">\n            <!-- Highway Road Surface -->\n            <rect x="20" y="120" width="360" height="50" fill="#1e293b"/>\n            <line x1="20" y1="145" x2="380" y2="145" stroke="#fde047" stroke-width="2" stroke-dasharray="8,8"/>\n\n            <!-- Milestones at 300, 350, 400 -->\n            <!-- 300 km Milestone -->\n            <g transform="translate(45, 80)">\n                <path d="M0,40 L0,15 A15,15 0 0,1 30,15 L30,40 Z" fill="#ffffff" stroke="#334155" stroke-width="1.5"/>\n                <path d="M0,15 A15,15 0 0,1 30,15 Z" fill="#0284c7"/>\n                <text x="15" y="32" fill="#020617" font-size="8" font-weight="bold" text-anchor="middle">300</text>\n            </g>\n\n            <!-- 350 km Midpoint Marker -->\n            <line x1="200" y1="120" x2="200" y2="170" stroke="#38bdf8" stroke-width="1.5" stroke-dasharray="3,3"/>\n            <text x="200" y="112" fill="#38bdf8" font-size="7.5" font-weight="bold" text-anchor="middle">Midpoint (350)</text>\n\n            <!-- 400 km Milestone -->\n            <g transform="translate(325, 80)">\n                <path d="M0,40 L0,15 A15,15 0 0,1 30,15 L30,40 Z" fill="#ffffff" stroke="#334155" stroke-width="1.5"/>\n                <path d="M0,15 A15,15 0 0,1 30,15 Z" fill="#16a34a"/>\n                <text x="15" y="32" fill="#020617" font-size="8" font-weight="bold" text-anchor="middle">400</text>\n            </g>\n\n            <!-- Highway Car Graphic -->\n            <g id="highwayCarMarker" transform="translate(130, 130)">\n                <rect x="0" y="6" width="36" height="14" rx="3" fill="#ea580c"/>\n                <polygon points="8,6 14,0 26,0 30,6" fill="#fde047"/>\n                <circle cx="8" cy="20" r="4" fill="#020617"/>\n                <circle cx="28" cy="20" r="4" fill="#020617"/>\n                <text id="carDistanceLabel" x="18" y="-4" fill="#fef08a" font-size="8" font-weight="bold" text-anchor="middle">328 km</text>\n            </g>\n\n            <!-- Result Readout Banner -->\n            <rect x="50" y="20" width="300" height="42" rx="6" fill="#020617" stroke="#334155" opacity="0.95"/>\n            <text id="milestoneResultText" x="200" y="38" fill="#fde047" font-size="10" font-weight="bold" text-anchor="middle">328 km: Tens digit is 2 (< 5)</text>\n            <text id="milestoneVerdictText" x="200" y="52" fill="#38bdf8" font-size="8" text-anchor="middle">Rounds DOWN to 300 km</text>\n        </svg>\n    </div>\n    <div class="grid grid-cols-3 gap-2">\n        <button onclick="setHighwayDistance(328)" class="p-2 bg-slate-900 hover:bg-slate-800 border border-sky-500 rounded-lg text-xs font-bold text-sky-300">\n            Test 328 km (→ 300)\n        </button>\n        <button onclick="setHighwayDistance(350)" class="p-2 bg-slate-900 hover:bg-slate-800 border border-amber-500 rounded-lg text-xs font-bold text-amber-300">\n            Test 350 km (→ 400)\n        </button>\n        <button onclick="setHighwayDistance(372)" class="p-2 bg-slate-900 hover:bg-slate-800 border border-emerald-500 rounded-lg text-xs font-bold text-emerald-300">\n            Test 372 km (→ 400)\n        </button>\n    </div>\n    <div id="sim8Status" class="p-2 bg-slate-900/60 rounded-lg border border-slate-800 text-[11px] text-slate-300">\n        <strong>Nearest 100 Rule:</strong> Look at the Tens digit! If tens digit is 5 or more (50 to 99), round up to the next hundred.\n    </div>\n</div>\n',
    9: '\n<div class="space-y-4">\n    <div class="bg-indigo-950/60 p-4 rounded-xl border border-indigo-500/30 text-center">\n        <h4 class="text-sm font-bold text-indigo-300 uppercase tracking-wider mb-1">Dual-Rounding Milestone Analyzer</h4>\n        <p class="text-xs text-slate-300">Discover fascinating numbers where rounding to the nearest 100 yields the EXACT same milestone as rounding to the nearest 1,000!</p>\n    </div>\n\n    <div class="grid grid-cols-2 sm:grid-cols-4 gap-2">\n        <button onclick="setRoundingNum(2980)" class="px-3 py-2 bg-slate-800 hover:bg-indigo-600 text-xs font-semibold rounded-lg text-white border border-slate-700 transition">Test 2,980</button>\n        <button onclick="setRoundingNum(4960)" class="px-3 py-2 bg-slate-800 hover:bg-indigo-600 text-xs font-semibold rounded-lg text-white border border-slate-700 transition">Test 4,960</button>\n        <button onclick="setRoundingNum(7975)" class="px-3 py-2 bg-slate-800 hover:bg-indigo-600 text-xs font-semibold rounded-lg text-white border border-slate-700 transition">Test 7,975</button>\n        <button onclick="setRoundingNum(3420)" class="px-3 py-2 bg-slate-800 hover:bg-indigo-600 text-xs font-semibold rounded-lg text-white border border-slate-700 transition">Test 3,420 (Differs)</button>\n    </div>\n\n    <div class="bg-slate-900/90 p-4 rounded-xl border border-slate-800">\n        <div class="flex items-center justify-between mb-3">\n            <span class="text-xs font-semibold text-slate-400">Current Value:</span>\n            <span id="currentRoundVal" class="text-xl font-bold font-mono text-amber-400">2,980</span>\n        </div>\n        <input type="range" id="roundSlider" min="2000" max="6000" step="10" value="2980" oninput="updateDualRounding(this.value)" class="w-full accent-indigo-500">\n        <div class="flex justify-between text-[11px] text-slate-400 font-mono mt-1">\n            <span>2,000</span>\n            <span>4,000</span>\n            <span>6,000</span>\n        </div>\n    </div>\n\n    <div class="grid grid-cols-1 sm:grid-cols-2 gap-3">\n        <div class="bg-slate-900/80 p-3.5 rounded-xl border border-blue-500/30">\n            <div class="flex justify-between items-center mb-1">\n                <span class="text-xs font-bold text-blue-300">Nearest Hundred (100s)</span>\n                <span class="text-[10px] px-2 py-0.5 bg-blue-950 text-blue-400 rounded">Look at Tens digit</span>\n            </div>\n            <div class="text-xl font-mono font-bold text-white mt-1" id="resRound100">3,000</div>\n            <p class="text-[11px] text-slate-400 mt-1" id="expRound100">Tens digit 8 &ge; 5 &rarr; Round up to 3,000</p>\n        </div>\n        <div class="bg-slate-900/80 p-3.5 rounded-xl border border-purple-500/30">\n            <div class="flex justify-between items-center mb-1">\n                <span class="text-xs font-bold text-purple-300">Nearest Thousand (1,000s)</span>\n                <span class="text-[10px] px-2 py-0.5 bg-purple-950 text-purple-400 rounded">Look at Hundreds digit</span>\n            </div>\n            <div class="text-xl font-mono font-bold text-white mt-1" id="resRound1000">3,000</div>\n            <p class="text-[11px] text-slate-400 mt-1" id="expRound1000">Hundreds digit 9 &ge; 5 &rarr; Round up to 3,000</p>\n        </div>\n    </div>\n\n    <div id="dualRoundBanner" class="p-3 bg-emerald-950/60 border border-emerald-500/40 rounded-xl text-center text-xs text-emerald-300 font-medium">\n        Awesome match! Both roundings land on 3,000!\n    </div>\n</div>\n',
    10: '\n<div class="space-y-4">\n    <div class="bg-cyan-950/60 p-4 rounded-xl border border-cyan-500/30 text-center">\n        <h4 class="text-sm font-bold text-cyan-300 uppercase tracking-wider mb-1">Distance = Speed &times; Time Flight Deck</h4>\n        <p class="text-xs text-slate-300">Compare historic and futuristic journeys across India and outer space over multiple hours.</p>\n    </div>\n\n    <div class="grid grid-cols-2 sm:grid-cols-4 gap-2">\n        <button onclick="setSpeedVehicle(\'walk\', 4)" class="px-2.5 py-2 bg-slate-800 hover:bg-cyan-600 text-xs font-medium rounded-lg text-white border border-slate-700 transition">Walking (4 km/h)</button>\n        <button onclick="setSpeedVehicle(\'train\', 120)" class="px-2.5 py-2 bg-slate-800 hover:bg-cyan-600 text-xs font-medium rounded-lg text-white border border-slate-700 transition">Train (120 km/h)</button>\n        <button onclick="setSpeedVehicle(\'flight\', 800)" class="px-2.5 py-2 bg-slate-800 hover:bg-cyan-600 text-xs font-medium rounded-lg text-white border border-slate-700 transition">Flight (800 km/h)</button>\n        <button onclick="setSpeedVehicle(\'rocket\', 28000)" class="px-2.5 py-2 bg-slate-800 hover:bg-cyan-600 text-xs font-medium rounded-lg text-white border border-slate-700 transition">Rocket (28,000 km/h)</button>\n    </div>\n\n    <div class="bg-slate-900/90 p-4 rounded-xl border border-slate-800 space-y-3">\n        <div class="flex justify-between items-center text-xs">\n            <span class="text-slate-400">Selected Vehicle: <strong id="selectedVehicleName" class="text-cyan-400">Train</strong></span>\n            <span class="text-slate-400">Speed: <strong id="selectedVehicleSpeed" class="text-white font-mono">120 km/h</strong></span>\n        </div>\n        <div>\n            <div class="flex justify-between items-center text-xs mb-1">\n                <span class="text-slate-400">Travel Duration:</span>\n                <span class="text-amber-400 font-bold font-mono" id="hoursVal">4 hours</span>\n            </div>\n            <input type="range" id="timeSlider" min="1" max="12" step="1" value="4" oninput="updateSpeedCalc(this.value)" class="w-full accent-cyan-500">\n            <div class="flex justify-between text-[10px] text-slate-400 font-mono mt-1">\n                <span>1 hr</span>\n                <span>3 hr</span>\n                <span>6 hr</span>\n                <span>9 hr</span>\n                <span>12 hr</span>\n            </div>\n        </div>\n    </div>\n\n    <div class="bg-gradient-to-r from-slate-900 via-indigo-950 to-slate-900 p-4 rounded-xl border border-indigo-500/30 text-center">\n        <div class="text-[11px] uppercase tracking-wider text-slate-400 font-semibold mb-1">Total Distance Covered</div>\n        <div class="text-2xl sm:text-3xl font-extrabold font-mono text-cyan-300" id="totalDistDisplay">480 km</div>\n        <div class="text-xs text-slate-300 mt-1 font-mono" id="distFormulaDisplay">120 km/h &times; 4 h = 480 km</div>\n    </div>\n</div>\n',
    11: '\n<div class="space-y-4">\n    <div class="bg-amber-950/60 p-4 rounded-xl border border-amber-500/30 text-center">\n        <h4 class="text-sm font-bold text-amber-300 uppercase tracking-wider mb-1">School Field Trip Fleet Dispatcher</h4>\n        <p class="text-xs text-slate-300">Calculate how many 50-seater standard buses and 15-seater mini-vans are needed for your school excursion.</p>\n    </div>\n\n    <div class="bg-slate-900/90 p-4 rounded-xl border border-slate-800">\n        <div class="flex items-center justify-between mb-2">\n            <span class="text-xs font-semibold text-slate-300">Total Students &amp; Teachers Going:</span>\n            <span id="tripHeadcount" class="text-lg font-bold font-mono text-amber-400">135 Passengers</span>\n        </div>\n        <input type="range" id="tripSlider" min="20" max="250" step="5" value="135" oninput="updateTripFleet(this.value)" class="w-full accent-amber-500">\n        <div class="flex justify-between text-[11px] text-slate-400 font-mono mt-1">\n            <span>20</span>\n            <span>75</span>\n            <span>135</span>\n            <span>200</span>\n            <span>250</span>\n        </div>\n    </div>\n\n    <div class="grid grid-cols-2 gap-3">\n        <div class="bg-slate-900/80 p-3.5 rounded-xl border border-amber-500/30 text-center">\n            <div class="text-xs text-slate-400 font-medium">Standard 50-Seater Buses</div>\n            <div class="text-2xl font-mono font-bold text-amber-300 mt-1" id="bus50Count">2 Buses</div>\n            <div class="text-[11px] text-slate-400 mt-0.5" id="bus50Seats">Carries 100 passengers</div>\n        </div>\n        <div class="bg-slate-900/80 p-3.5 rounded-xl border border-blue-500/30 text-center">\n            <div class="text-xs text-slate-400 font-medium">Mini 15-Seater Vans</div>\n            <div class="text-2xl font-mono font-bold text-blue-300 mt-1" id="van15Count">3 Vans</div>\n            <div class="text-[11px] text-slate-400 mt-0.5" id="van15Seats">Carries remaining 35 (45 seats)</div>\n        </div>\n    </div>\n\n    <div class="p-3 bg-slate-900 rounded-xl border border-slate-800 text-xs text-slate-300 space-y-1">\n        <div class="flex justify-between">\n            <span>Total Seats Booked:</span>\n            <span class="font-mono font-bold text-emerald-400" id="totalSeatsBooked">145 seats</span>\n        </div>\n        <div class="flex justify-between">\n            <span>Empty Spare Seats:</span>\n            <span class="font-mono font-bold text-slate-400" id="emptySeatsCount">10 seats</span>\n        </div>\n    </div>\n</div>\n',
    12: '\n<div class="space-y-4">\n    <div class="bg-teal-950/60 p-4 rounded-xl border border-teal-500/30 text-center">\n        <h4 class="text-sm font-bold text-teal-300 uppercase tracking-wider mb-1">Real-World 5-Digit Number Scope</h4>\n        <p class="text-xs text-slate-300">Tap everyday scenarios to visualize just how vast numbers between 10,000 and 100,000 really are!</p>\n    </div>\n\n    <div class="grid grid-cols-2 sm:grid-cols-4 gap-2">\n        <button onclick="setContextNumber(\'book\', 18450, \'Words in Joyful Maths Textbook\', \'TTh: 1, Th: 8, H: 4, T: 5, O: 0\')" class="px-2.5 py-2 bg-slate-800 hover:bg-teal-600 text-xs font-semibold rounded-lg text-white border border-slate-700 transition">Book Words</button>\n        <button onclick="setContextNumber(\'stadium\', 42500, \'Spectators at Cricket Stadium\', \'TTh: 4, Th: 2, H: 5, T: 0, O: 0\')" class="px-2.5 py-2 bg-slate-800 hover:bg-teal-600 text-xs font-semibold rounded-lg text-white border border-slate-700 transition">Cricket Match</button>\n        <button onclick="setContextNumber(\'forest\', 25680, \'Trees in Forest Reserve\', \'TTh: 2, Th: 5, H: 6, T: 8, O: 0\')" class="px-2.5 py-2 bg-slate-800 hover:bg-teal-600 text-xs font-semibold rounded-lg text-white border border-slate-700 transition">Reserve Trees</button>\n        <button onclick="setContextNumber(\'town\', 68900, \'Town Population Census\', \'TTh: 6, Th: 8, H: 9, T: 0, O: 0\')" class="px-2.5 py-2 bg-slate-800 hover:bg-teal-600 text-xs font-semibold rounded-lg text-white border border-slate-700 transition">Town Census</button>\n    </div>\n\n    <div class="bg-slate-900/90 p-4 rounded-xl border border-slate-800 text-center space-y-2">\n        <div class="text-xs text-teal-400 font-semibold" id="contextTitle">Words in Joyful Maths Textbook</div>\n        <div class="text-3xl sm:text-4xl font-extrabold font-mono text-white tracking-wider" id="contextNum">18,450</div>\n        <div class="text-xs text-slate-400" id="contextWords">Eighteen thousand four hundred fifty</div>\n    </div>\n\n    <div class="bg-slate-900/80 p-3.5 rounded-xl border border-teal-500/20">\n        <div class="text-xs font-semibold text-slate-400 mb-2">Place Value Breakdown:</div>\n        <div class="grid grid-cols-5 gap-2 text-center text-xs font-mono" id="contextBreakdown">\n            <div class="bg-teal-950/60 p-2 rounded border border-teal-500/30"><div class="text-[10px] text-teal-400">TTh</div><div class="font-bold text-white text-base">1</div><div class="text-[9px] text-slate-400">10,000</div></div>\n            <div class="bg-cyan-950/60 p-2 rounded border border-cyan-500/30"><div class="text-[10px] text-cyan-400">Th</div><div class="font-bold text-white text-base">8</div><div class="text-[9px] text-slate-400">8,000</div></div>\n            <div class="bg-blue-950/60 p-2 rounded border border-blue-500/30"><div class="text-[10px] text-blue-400">H</div><div class="font-bold text-white text-base">4</div><div class="text-[9px] text-slate-400">400</div></div>\n            <div class="bg-indigo-950/60 p-2 rounded border border-indigo-500/30"><div class="text-[10px] text-indigo-400">T</div><div class="font-bold text-white text-base">5</div><div class="text-[9px] text-slate-400">50</div></div>\n            <div class="bg-violet-950/60 p-2 rounded border border-violet-500/30"><div class="text-[10px] text-violet-400">O</div><div class="font-bold text-white text-base">0</div><div class="text-[9px] text-slate-400">0</div></div>\n        </div>\n    </div>\n</div>\n',
    13: '\n<div class="space-y-4">\n    <div class="bg-emerald-950/60 p-4 rounded-xl border border-emerald-500/30 text-center">\n        <h4 class="text-sm font-bold text-emerald-300 uppercase tracking-wider mb-1">River Crossing Logic Game</h4>\n        <p class="text-xs text-slate-300">Help the boatman ferry the Lion, Sheep, and Grass across the river safely. The boat can carry only the boatman plus ONE passenger!</p>\n    </div>\n\n    <!-- River Scene -->\n    <div class="bg-slate-900/90 p-4 rounded-xl border border-slate-800">\n        <div class="grid grid-cols-3 gap-2 text-center text-xs">\n            <div class="bg-slate-950/80 p-3 rounded-lg border border-slate-800">\n                <div class="font-bold text-emerald-400 mb-2">Left Bank (Start)</div>\n                <div id="leftBankItems" class="flex flex-wrap justify-center gap-1.5 min-h-[50px]">\n                    <span class="px-2 py-1 bg-amber-900/60 border border-amber-600/40 rounded text-amber-200">🦁 Lion</span>\n                    <span class="px-2 py-1 bg-blue-900/60 border border-blue-600/40 rounded text-blue-200">🐑 Sheep</span>\n                    <span class="px-2 py-1 bg-green-900/60 border border-green-600/40 rounded text-green-200">🌾 Grass</span>\n                </div>\n            </div>\n\n            <div class="bg-blue-950/40 p-3 rounded-lg border border-blue-500/30 flex flex-col justify-between">\n                <div class="font-bold text-blue-300">River &amp; Boat</div>\n                <div id="boatDisplay" class="my-auto py-2 px-1 bg-amber-950/80 rounded border border-amber-700/50">\n                    <div class="text-[11px] text-amber-300 font-semibold">🚣 Boatman (Left Bank)</div>\n                    <div id="boatCargo" class="text-xs text-slate-400 mt-0.5">Empty</div>\n                </div>\n                <div class="text-[10px] text-slate-400">Capacity: 1 item</div>\n            </div>\n\n            <div class="bg-slate-950/80 p-3 rounded-lg border border-slate-800">\n                <div class="font-bold text-teal-400 mb-2">Right Bank (Goal)</div>\n                <div id="rightBankItems" class="flex flex-wrap justify-center gap-1.5 min-h-[50px]">\n                    <span class="text-slate-500 italic text-[11px]">None yet</span>\n                </div>\n            </div>\n        </div>\n\n        <div id="riverGameStatus" class="mt-3 p-2 bg-slate-950 rounded text-center text-xs text-slate-300 border border-slate-800">\n            Rules: Lion eats Sheep if left alone. Sheep eats Grass if left alone.\n        </div>\n    </div>\n\n    <!-- Action Controls -->\n    <div class="flex flex-wrap justify-center gap-2">\n        <button onclick="riverLoad(\'lion\')" class="px-3 py-1.5 bg-amber-900/80 hover:bg-amber-700 text-amber-200 text-xs font-semibold rounded-lg border border-amber-600/40 transition">Board 🦁 Lion</button>\n        <button onclick="riverLoad(\'sheep\')" class="px-3 py-1.5 bg-blue-900/80 hover:bg-blue-700 text-blue-200 text-xs font-semibold rounded-lg border border-blue-600/40 transition">Board 🐑 Sheep</button>\n        <button onclick="riverLoad(\'grass\')" class="px-3 py-1.5 bg-green-900/80 hover:bg-green-700 text-green-200 text-xs font-semibold rounded-lg border border-green-600/40 transition">Board 🌾 Grass</button>\n        <button onclick="riverRowBoat()" class="px-4 py-1.5 bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-bold rounded-lg transition shadow">Row Boat &rarr;</button>\n        <button onclick="riverReset()" class="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-300 text-xs font-semibold rounded-lg border border-slate-700 transition">Reset</button>\n        <button onclick="riverAutoSolve()" class="px-3 py-1.5 bg-emerald-700 hover:bg-emerald-600 text-white text-xs font-bold rounded-lg transition">Show Solution</button>\n    </div>\n</div>\n',
    14: '\n<div class="space-y-4">\n    <div class="bg-violet-950/60 p-4 rounded-xl border border-violet-500/30 text-center">\n        <h4 class="text-sm font-bold text-violet-300 uppercase tracking-wider mb-1">Pile of Pebbles Strategy Lab</h4>\n        <p class="text-xs text-slate-300">Start with 15 pebbles. Each turn, take 1, 2, or 3 pebbles. The player who takes the last pebble wins! Discover the multiple-of-4 strategy.</p>\n    </div>\n\n    <div class="bg-slate-900/90 p-4 rounded-xl border border-slate-800 text-center">\n        <div class="text-xs text-slate-400 font-semibold mb-2">Pebbles Remaining: <span id="pebbleCountDisplay" class="text-2xl font-bold font-mono text-amber-400 ml-1">15</span></div>\n        <div id="pebblesContainer" class="flex flex-wrap justify-center gap-2 min-h-[50px] p-2 bg-slate-950/70 rounded-lg border border-slate-800">\n            <!-- Pebbles rendered dynamically -->\n        </div>\n        <div class="text-xs text-slate-400 mt-2" id="pebbleStrategyHint">Winning secret: 15 = 4 &times; 3 + 3. Leave your opponent with a multiple of 4!</div>\n    </div>\n\n    <div class="grid grid-cols-3 gap-2">\n        <button onclick="playerTakePebbles(1)" class="px-3 py-2 bg-slate-800 hover:bg-violet-600 text-xs font-bold text-white rounded-lg border border-slate-700 transition">Take 1 Pebble</button>\n        <button onclick="playerTakePebbles(2)" class="px-3 py-2 bg-slate-800 hover:bg-violet-600 text-xs font-bold text-white rounded-lg border border-slate-700 transition">Take 2 Pebbles</button>\n        <button onclick="playerTakePebbles(3)" class="px-3 py-2 bg-slate-800 hover:bg-violet-600 text-xs font-bold text-white rounded-lg border border-slate-700 transition">Take 3 Pebbles</button>\n    </div>\n\n    <div id="pebbleGameStatus" class="p-3 bg-indigo-950/60 border border-indigo-500/30 rounded-xl text-xs text-indigo-300 text-center">\n        Your turn! Pick 1, 2, or 3 pebbles.\n    </div>\n\n    <div class="flex justify-center">\n        <button onclick="resetPebblesGame()" class="px-4 py-1.5 bg-slate-800 hover:bg-slate-700 text-xs font-semibold text-slate-300 rounded-lg border border-slate-700 transition">Restart Game (15 Pebbles)</button>\n    </div>\n</div>\n',
    15: '\n<div class="space-y-4">\n    <div class="bg-fuchsia-950/60 p-4 rounded-xl border border-fuchsia-500/30 text-center">\n        <h4 class="text-sm font-bold text-fuchsia-300 uppercase tracking-wider mb-1">Magic 9 Digit-Difference Engine</h4>\n        <p class="text-xs text-slate-300">Choose two distinct digits (a &gt; b). Reverse them to form two 2-digit numbers and subtract. The difference is ALWAYS a multiple of 9!</p>\n    </div>\n\n    <div class="grid grid-cols-2 gap-3 bg-slate-900/90 p-4 rounded-xl border border-slate-800">\n        <div>\n            <label class="block text-xs font-semibold text-slate-300 mb-1">Digit a (Tens):</label>\n            <select id="digitASelect" onchange="calcDigitDiff()" class="w-full bg-slate-800 border border-slate-700 text-white rounded px-3 py-1.5 text-xs font-mono">\n                <option value="9">9</option>\n                <option value="8" selected>8</option>\n                <option value="7">7</option>\n                <option value="6">6</option>\n                <option value="5">5</option>\n            </select>\n        </div>\n        <div>\n            <label class="block text-xs font-semibold text-slate-300 mb-1">Digit b (Ones):</label>\n            <select id="digitBSelect" onchange="calcDigitDiff()" class="w-full bg-slate-800 border border-slate-700 text-white rounded px-3 py-1.5 text-xs font-mono">\n                <option value="3" selected>3</option>\n                <option value="2">2</option>\n                <option value="1">1</option>\n                <option value="0">0</option>\n            </select>\n        </div>\n    </div>\n\n    <div class="bg-slate-900/80 p-4 rounded-xl border border-fuchsia-500/30 space-y-2 text-center font-mono">\n        <div class="text-xs text-slate-400">Step-by-Step Subtraction:</div>\n        <div class="text-xl font-bold text-white" id="diffEquation">83 &minus; 38 = 45</div>\n        <div class="text-xs text-fuchsia-400 font-bold" id="diffMultiple">45 = 9 &times; 5</div>\n        <div class="text-[11px] text-slate-300 mt-1" id="diffProof">Notice: 9 &times; (8 &minus; 3) = 9 &times; 5 = 45!</div>\n    </div>\n\n    <div class="p-3 bg-slate-950 rounded-xl border border-slate-800 text-xs text-slate-300">\n        <strong class="text-amber-400">Algebraic Proof:</strong> Any 2-digit number is 10a + b. Its reverse is 10b + a. Their difference is (10a + b) &minus; (10b + a) = 9a &minus; 9b = <strong>9 &times; (a &minus; b)</strong>. It is always divisible by 9!\n    </div>\n</div>\n',
    16: '\n<div class="space-y-4">\n    <div class="bg-rose-950/60 p-4 rounded-xl border border-rose-500/30 text-center">\n        <h4 class="text-sm font-bold text-rose-300 uppercase tracking-wider mb-1">King\'s Horses Stable Trick</h4>\n        <p class="text-xs text-slate-300">The King inspects his square 3&times;3 stable and demands 5 horses on each of the 4 outer sides. Can 18 horses satisfy this? Yes, using corner-sharing!</p>\n    </div>\n\n    <!-- 3x3 Stable Grid -->\n    <div class="bg-slate-900/90 p-4 rounded-xl border border-slate-800 max-w-xs mx-auto">\n        <div class="grid grid-cols-3 gap-2 text-center font-mono">\n            <!-- Top Row -->\n            <div id="cellTL" class="p-3 bg-amber-950/70 border border-amber-600/40 rounded-lg">\n                <div class="text-[10px] text-amber-300">Corner</div>\n                <div class="text-lg font-bold text-white" id="valTL">2</div>\n            </div>\n            <div id="cellTM" class="p-3 bg-slate-800 border border-slate-700 rounded-lg">\n                <div class="text-[10px] text-slate-400">Middle</div>\n                <div class="text-lg font-bold text-white" id="valTM">1</div>\n            </div>\n            <div id="cellTR" class="p-3 bg-amber-950/70 border border-amber-600/40 rounded-lg">\n                <div class="text-[10px] text-amber-300">Corner</div>\n                <div class="text-lg font-bold text-white" id="valTR">2</div>\n            </div>\n\n            <!-- Middle Row -->\n            <div id="cellML" class="p-3 bg-slate-800 border border-slate-700 rounded-lg">\n                <div class="text-[10px] text-slate-400">Middle</div>\n                <div class="text-lg font-bold text-white" id="valML">1</div>\n            </div>\n            <div class="p-3 bg-slate-950 border border-slate-800 rounded-lg flex items-center justify-center">\n                <span class="text-[11px] text-slate-500 font-sans">Courtyard</span>\n            </div>\n            <div id="cellMR" class="p-3 bg-slate-800 border border-slate-700 rounded-lg">\n                <div class="text-[10px] text-slate-400">Middle</div>\n                <div class="text-lg font-bold text-white" id="valMR">1</div>\n            </div>\n\n            <!-- Bottom Row -->\n            <div id="cellBL" class="p-3 bg-amber-950/70 border border-amber-600/40 rounded-lg">\n                <div class="text-[10px] text-amber-300">Corner</div>\n                <div class="text-lg font-bold text-white" id="valBL">0</div>\n            </div>\n            <div id="cellBM" class="p-3 bg-slate-800 border border-slate-700 rounded-lg">\n                <div class="text-[10px] text-slate-400">Middle</div>\n                <div class="text-lg font-bold text-white" id="valBM">5</div>\n            </div>\n            <div id="cellBR" class="p-3 bg-amber-950/70 border border-amber-600/40 rounded-lg">\n                <div class="text-[10px] text-amber-300">Corner</div>\n                <div class="text-lg font-bold text-white" id="valBR">0</div>\n            </div>\n        </div>\n    </div>\n\n    <!-- Side Sums & Total -->\n    <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs font-mono">\n        <div class="bg-slate-900 p-2 rounded-lg border border-slate-800">\n            <span class="text-slate-400">Top Side:</span>\n            <div class="text-emerald-400 font-bold" id="sumTop">5 horses &check;</div>\n        </div>\n        <div class="bg-slate-900 p-2 rounded-lg border border-slate-800">\n            <span class="text-slate-400">Bottom Side:</span>\n            <div class="text-emerald-400 font-bold" id="sumBottom">5 horses &check;</div>\n        </div>\n        <div class="bg-slate-900 p-2 rounded-lg border border-slate-800">\n            <span class="text-slate-400">Left Side:</span>\n            <div class="text-emerald-400 font-bold" id="sumLeft">5 horses &check;</div>\n        </div>\n        <div class="bg-slate-900 p-2 rounded-lg border border-slate-800">\n            <span class="text-slate-400">Right Side:</span>\n            <div class="text-emerald-400 font-bold" id="sumRight">5 horses &check;</div>\n        </div>\n    </div>\n\n    <div class="flex flex-wrap justify-center gap-2">\n        <button onclick="setStableConfig(\'all_middle\')" class="px-3 py-1.5 bg-slate-800 hover:bg-rose-600 text-xs font-semibold rounded-lg text-white border border-slate-700 transition">Config 1: 20 Horses (0 in Corners)</button>\n        <button onclick="setStableConfig(\'stolen_18\')" class="px-3 py-1.5 bg-slate-800 hover:bg-rose-600 text-xs font-semibold rounded-lg text-white border border-slate-700 transition">Config 2: 18 Horses (2 in Corners)</button>\n        <button onclick="setStableConfig(\'stolen_16\')" class="px-3 py-1.5 bg-slate-800 hover:bg-rose-600 text-xs font-semibold rounded-lg text-white border border-slate-700 transition">Config 3: 16 Horses (4 in Corners)</button>\n    </div>\n\n    <div class="p-3 bg-slate-900 rounded-xl border border-slate-800 text-xs text-slate-300 text-center">\n        <span class="text-amber-400 font-bold">Mathematical Formula:</span> Total Horses = 4 &times; 5 &minus; C = <strong>20 &minus; C</strong> (where C = sum of horses in 4 corners). Each corner horse is counted on TWO sides!\n    </div>\n</div>\n',
}
